import{_ as n,C as s,o as d,c as e,a2 as r,j as i,E as t,a as l}from"./chunks/framework.C21TwvGF.js";const O=JSON.parse('{"title":"3-dars (Mentor). Androidning imkoniyatlari va qo‘llanilish sohalari","description":"","frontmatter":{"title":"3-dars (Mentor). Androidning imkoniyatlari va qo‘llanilish sohalari","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Android)","link":"/mentor/9-sinf-android/"},"week":{"n":1,"link":"/mentor/9-sinf-android/hafta-01/"},"g":3,"title":"Androidning imkoniyatlari va qo‘llanilish sohalari","lead":"Androidning imkoniyatlari va qo‘llanilish sohalari: smartfon, planshet, WearOS, Android Auto, Android TV va IoT","slide":"/slaydlar/9-sinf-android/hafta-01/dars-3.html","test":"/slaydlar/9-sinf-android/hafta-01/dars-3-test.html","student_link":"/9-sinf-android/hafta-01/dars-3","tabs":[{"g":1,"link":"/mentor/9-sinf-android/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/9-sinf-android/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/9-sinf-android/hafta-01/dars-3","current":true}],"prev":{"g":2,"title":"Android tizimi va uning arxitekturasi","link":"/mentor/9-sinf-android/hafta-01/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-android/hafta-01/dars-3.md","filePath":"mentor/9-sinf-android/hafta-01/dars-3.md"}'),h={name:"mentor/9-sinf-android/hafta-01/dars-3.md"},u={class:"blk"},m={id:"_1-dars-maqsadi-va-kutiladigan-natijalar",tabindex:"-1"},g={class:"blk"},v={id:"_2-dars-rejasi-80-daqiqa",tabindex:"-1"},q={class:"blk"},k={id:"_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt",tabindex:"-1"},y={class:"blk"},b={id:"_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari",tabindex:"-1"},f={class:"blk"},A={id:"_5-tezkor-savol-javob-blits-savollar",tabindex:"-1"},p={class:"blk"},c={id:"_6-mentor-uchun-amaliy-tavsiyalar",tabindex:"-1"};function _(T,a,z,x,S,P){const o=s("Icon");return d(),e("div",null,[a[18]||(a[18]=r("<p><strong>Sinf:</strong> 9-sinf (Android dasturlash)<br><strong>Hafta:</strong> 1-hafta<br><strong>Dars tartibi:</strong> 3-dars (umumiy 102 darsdan 3-darsi)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Format:</strong> Amaliy va tahliliy mashg&#39;ulot</p><hr>",2)),i("div",u,[i("h2",m,[t(o,{name:"file-text"}),a[0]||(a[0]=l(" 1. Dars maqsadi va kutiladigan natijalar ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-maqsadi-va-kutiladigan-natijalar","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars maqsadi va kutiladigan natijalar"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Maqsad:</strong> O&#39;quvchilarga Android platformasining texnik imkoniyatlari (ko&#39;p vazifalilik, on-device AI/ML, bulutli integratsiya) hamda uning smartfonlardan tashqari turli xil sohalarda (Wear OS, Android Auto, Android TV, IoT va tibbiyot) qo&#39;llanilishi bo&#39;yicha to&#39;liq tasavvur berish.</li><li><strong>Kutiladigan natijalar:</strong><ul><li>O&#39;quvchi Androidning multitasking (Split-screen, Picture-in-Picture) va sun&#39;iy intellekt imkoniyatlarini tushuntira oladi;</li><li>Android faqat telefon operatsion tizimi emas, balki global ekotizim ekanini anglaydi;</li><li>Wear OS (aqlli soatlar), Android Auto (avtomobil tizimlari), Android TV (televizorlar) va IoT qurilmalarining o&#39;ziga xos arxitekturasini ajrata oladi;</li><li>Har xil turdagi ekran o&#39;lchamlari va moslashuvchan dizayn (Responsive / Adaptive UI) tushunchasini biladi;</li><li>Tibbiyot, transport, ta&#39;lim va savdo sohalarida Android asosidagi ixtisoslashgan qurilmalar (POS-terminallar, tibbiy monitorlar, interaktiv panellar) rolini tahlil qila oladi.</li></ul></li></ul><hr>",2))]),i("div",g,[i("h2",v,[t(o,{name:"file-text"}),a[3]||(a[3]=l(" 2. Dars rejasi (80 daqiqa) ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars rejasi (80 daqiqa)"'},"​",-1))]),a[5]||(a[5]=r('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Tavsif</th></tr></thead><tbody><tr><td><strong>00–10 daq</strong></td><td>O&#39;tgan mavzuni takrorlash va kirish</td><td>Androidning 5 qatlami, ART va Sandbox bo&#39;yicha blits-so&#39;rov. Muammoli savol: &quot;Aqlli soat va avtomobil ekranidagi Android smartfondagidan nimasi bilan farq qiladi?&quot;</td></tr><tr><td><strong>10–35 daq</strong></td><td>Yangi mavzu: Texnik imkoniyatlar</td><td>Multitasking (Split-screen, PiP), on-device sun&#39;iy intellekt (Gemini Nano, NNAPI), bulutli texnologiyalar bilan integratsiya</td></tr><tr><td><strong>35–55 daq</strong></td><td>Yangi mavzu: Qo&#39;llanilish sohalari</td><td>Wear OS (aqlli soatlar), Android Auto / Automotive OS (avtomobillar), Android TV, IoT va sanoat qurilmalari</td></tr><tr><td><strong>55–65 daq</strong></td><td>Amaliy keys va guruhlarda tahlil</td><td>Turli qurilmalar uchun foydalanuvchi interfeysi (UI/UX) cheklovlarini solishtirish (soat ekrani vs televizor ekrani)</td></tr><tr><td><strong>65–75 daq</strong></td><td>Mustahkamlash va test sinovi</td><td>Interaktiv savol-javob, konspekt tekshiruvi</td></tr><tr><td><strong>75–80 daq</strong></td><td>Xulosa va 1-hafta sarhisobi</td><td>Dars xulosasi, baholash, 1-haftaning umumiy uyga vazifasini tushuntirish</td></tr></tbody></table><hr>',2))]),i("div",q,[i("h2",k,[t(o,{name:"file-text"}),a[6]||(a[6]=l(" 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt) ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt","aria-label":`Permalink to "<Icon name="file-text" /> 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt)"`},"​",-1))]),a[8]||(a[8]=r('<h3 id="_3-1-androidning-zamonaviy-texnik-imkoniyatlari" tabindex="-1">3.1. Androidning zamonaviy texnik imkoniyatlari <a class="header-anchor" href="#_3-1-androidning-zamonaviy-texnik-imkoniyatlari" aria-label="Permalink to &quot;3.1. Androidning zamonaviy texnik imkoniyatlari&quot;">​</a></h3><p>Android platformasi rivojlanish jarayonida oddiy mobil telefondan qudratli hisoblash platformasiga aylandi:</p><ol><li><strong>Ko&#39;p vazifalilik (Multitasking):</strong><ul><li><strong>Split-Screen (Ekranni ikkiga bo&#39;lish):</strong> Bir vaqtning o&#39;zida ikkita ilovadan (masalan, yuqorida YouTube videosi, pastda konspekt ilovasi) teng foydalanish;</li><li><strong>Picture-in-Picture (PiP — Rasmdagi rasm):</strong> Video qo&#39;ng&#39;iroq yoki xarita mini-oyna ko&#39;rinishida ekranning bir burchagida suzib yuradi;</li><li><strong>Freeform Windows:</strong> Planshetlar va buklanuvchi (Foldable) qurilmalarda xuddi kompyuterdagidek oynalarni erkin ko&#39;chirish va o&#39;lchamini o&#39;zgartirish.</li></ul></li><li><strong>Sun&#39;iy intellekt va mashinali o&#39;rganish (On-Device AI/ML):</strong><ul><li>Zamonaviy Android versiyalarida (Android 14–15) AI hisob-kitoblari internetga so&#39;rov yubormasdan to&#39;g&#39;ridan-to&#39;g&#39;ri qurilmaning NPU (Neural Processing Unit) chipida amalga oshiriladi;</li><li><strong>Android AICore va Gemini Nano:</strong> Ovozni real vaqtda matnga aylantirish, matnlarni umumlashtirish (summarize), aqlli avto-javoblar.</li></ul></li><li><strong>Bulutli sinxronizatsiya:</strong><ul><li>Google Drive, Firebase va Cloud Messaging orqali bir qurilmada boshlangan ish boshqa qurilmada bir zumda davom ettiriladi.</li></ul></li></ol><h3 id="_3-2-qo-llanilish-sohalari-va-ixtisoslashgan-android-versiyalari" tabindex="-1">3.2. Qo&#39;llanilish sohalari va ixtisoslashgan Android versiyalari <a class="header-anchor" href="#_3-2-qo-llanilish-sohalari-va-ixtisoslashgan-android-versiyalari" aria-label="Permalink to &quot;3.2. Qo&#39;llanilish sohalari va ixtisoslashgan Android versiyalari&quot;">​</a></h3><p>Google Android yadrosi asosida turli qurilmalar sinfi uchun moslashtirilgan maxsus versiyalarni ishlab chiqqan:</p><h4 id="_1-smartfonlar-planshetlar-va-foldable-qurilmalar" tabindex="-1">1. Smartfonlar, planshetlar va Foldable qurilmalar <a class="header-anchor" href="#_1-smartfonlar-planshetlar-va-foldable-qurilmalar" aria-label="Permalink to &quot;1. Smartfonlar, planshetlar va Foldable qurilmalar&quot;">​</a></h4><ul><li>Har xil o&#39;lchamli ekranlar (5 dyuymdan 14 dyuymgacha);</li><li>Buklanuvchi ekranlar (Samsung Galaxy Fold, Pixel Fold) uchun maxsus moslashuvchan oynalar (Adaptive Layouts).</li></ul><h4 id="_2-wear-os-aqlli-soatlar" tabindex="-1">2. Wear OS (Aqlli soatlar) <a class="header-anchor" href="#_2-wear-os-aqlli-soatlar" aria-label="Permalink to &quot;2. Wear OS (Aqlli soatlar)&quot;">​</a></h4><ul><li><strong>Ekran o&#39;lchami:</strong> 1.2 – 1.5 dyuymli dumaloq yoki to&#39;rtburchak ekranlar;</li><li><strong>Asosiy vazifasi:</strong> Sog&#39;liqni nazorat qilish (yurak urish tezligi — puls, qon bosimi, EKG, qadamlar), tezkor bildirishnomalar, kontaktsiz to&#39;lov (NFC orqali);</li><li><strong>Dasturlash xususiyati:</strong> Batareyani maksimal tejash, minimalistik interfeys (Tiles va Complications), doimiy ochiq ekran (Always-on Display).</li></ul><h4 id="_3-android-auto-va-android-automotive-os" tabindex="-1">3. Android Auto va Android Automotive OS <a class="header-anchor" href="#_3-android-auto-va-android-automotive-os" aria-label="Permalink to &quot;3. Android Auto va Android Automotive OS&quot;">​</a></h4><ul><li><strong>Android Auto:</strong> Smartfon ekranini avtomobil monitoriga proyeksiyalovchi tizim (kabel yoki simsiz ulanish);</li><li><strong>Android Automotive OS (AAOS):</strong> Avtomobilning o&#39;ziga o&#39;rnatilgan mustaqil operatsion tizim (Volvo, Polestar, Ford). U nafaqat musiqa va navigatsiyani, balki konditsioner, o&#39;rindiq isitish va akkumulyator quvvatini ham boshqaradi;</li><li><strong>Xavfsizlik qoidasi:</strong> Dasturchi haydovchining e&#39;tiborini chalg&#39;itmaydigan yirik tugmalar va ovozli boshqaruvga (Google Assistant) asoslangan interfeys yaratishi shart.</li></ul><h4 id="_4-android-tv-va-google-tv" tabindex="-1">4. Android TV va Google TV <a class="header-anchor" href="#_4-android-tv-va-google-tv" aria-label="Permalink to &quot;4. Android TV va Google TV&quot;">​</a></h4><ul><li>Katta ekranlar (32 dyuymdan 85+ dyuymgacha);</li><li>Sensorli boshqaruv yo&#39;q: foydalanuvchi pult (D-pad: yuqori, pastki, chap, o&#39;ng, OK) orqali boshqaradi;</li><li>Ko&#39;rish masofasi: 2.5–3 metr (&quot;10-foot UI&quot;);</li><li>Qo&#39;llanilishi: YouTube, Netflix, onlayn kinoteatrlar, o&#39;yinlar.</li></ul><h4 id="_5-iot-internet-of-things-—-buyumlar-interneti-va-sanoat-qurilmalari" tabindex="-1">5. IoT (Internet of Things — Buyumlar Interneti) va sanoat qurilmalari <a class="header-anchor" href="#_5-iot-internet-of-things-—-buyumlar-interneti-va-sanoat-qurilmalari" aria-label="Permalink to &quot;5. IoT (Internet of Things — Buyumlar Interneti) va sanoat qurilmalari&quot;">​</a></h4><ul><li><strong>Savdo va xizmat ko&#39;rsatish:</strong> Android asosida ishlaydigan aqlli kassa va POS-terminallar (masalan, chek chiqaruvchi Smart POS apparatlari);</li><li><strong>Tibbiyot:</strong> Bemor parametrlarini kuzatuvchi statsionar monitorlar;</li><li><strong>Aqlli uy:</strong> Muzlatgich eshigidagi sensorli ekran, aqlli domofonlar va devor panellari.</li></ul><hr>',16))]),i("div",y,[i("h2",b,[t(o,{name:"file-text"}),a[9]||(a[9]=l(" 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari","aria-label":'Permalink to "<Icon name="file-text" /> 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari"'},"​",-1))]),a[11]||(a[11]=r('<h3 id="_1-topshiriq-turli-qurilmalar-interfeysi-taqqoslash-jadvali-oson" tabindex="-1">1-topshiriq. Turli qurilmalar interfeysi taqqoslash jadvali (Oson) <a class="header-anchor" href="#_1-topshiriq-turli-qurilmalar-interfeysi-taqqoslash-jadvali-oson" aria-label="Permalink to &quot;1-topshiriq. Turli qurilmalar interfeysi taqqoslash jadvali (Oson)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Smartfon, Wear OS (aqlli soat) va Android TV qurilmalarini ekran o&#39;lchami, boshqaruv turi va asosiy vazifasi bo&#39;yicha taqqoslang.</p><p><strong>Yechim:</strong></p><table tabindex="0"><thead><tr><th>Qurilma turi</th><th>Ekran o&#39;lchami</th><th>Boshqaruv turi</th><th>Asosiy maqsadi</th></tr></thead><tbody><tr><td><strong>Smartfon</strong></td><td>5.5 – 6.8 dyuym</td><td>Sensorli ekran (Touch, Multi-touch)</td><td>To&#39;liq kommunikatsiya, internet, ish va o&#39;yinlar</td></tr><tr><td><strong>Wear OS</strong></td><td>1.2 – 1.5 dyuym</td><td>Kichik sensorli ekran, aylanuvchi tugma (Crown), ovoz</td><td>Tezkor xabarlar, sport va salomatlik nazorati</td></tr><tr><td><strong>Android TV</strong></td><td>32 – 85+ dyuym</td><td>Masofadan boshqarish pulti (D-pad), ovoz</td><td>Video va multimedia ko&#39;rish, qulay hordiq</td></tr></tbody></table><h3 id="_2-topshiriq-android-auto-va-android-automotive-os-farqi-o-rta" tabindex="-1">2-topshiriq. Android Auto va Android Automotive OS farqi (O&#39;rta) <a class="header-anchor" href="#_2-topshiriq-android-auto-va-android-automotive-os-farqi-o-rta" aria-label="Permalink to &quot;2-topshiriq. Android Auto va Android Automotive OS farqi (O&#39;rta)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Nima sababdan Android Auto va Android Automotive OS ikki xil texnologiya hisoblanadi? Ularning asosiy farqini tushuntiring.</p><p><strong>Yechim:</strong></p><ul><li><strong>Android Auto:</strong> Bu mustaqil operatsion tizim emas. U haydovchining smartfonida ishlaydi va avtomobil ekraniga tasvirni uzatadi (Screen Casting). Agar smartfon uzilsa, tizim ishlamaydi.</li><li><strong>Android Automotive OS (AAOS):</strong> Bu avtomobilning bort kompyuteriga o&#39;rnatilgan to&#39;laqonli mustaqil operatsion tizimdir. U smartfonga bog&#39;liq emas, avtomobil apparatiga (konditsioner, batareya holati, tezlik) to&#39;g&#39;ridan-to&#39;g&#39;ri ulangan.</li></ul><h3 id="_3-topshiriq-iot-qurilmasi-uchun-android-ilovasi-konsepsiyasi-qiyin" tabindex="-1">3-topshiriq. IoT qurilmasi uchun Android ilovasi konsepsiyasi (Qiyin) <a class="header-anchor" href="#_3-topshiriq-iot-qurilmasi-uchun-android-ilovasi-konsepsiyasi-qiyin" aria-label="Permalink to &quot;3-topshiriq. IoT qurilmasi uchun Android ilovasi konsepsiyasi (Qiyin)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Maktab oshxonasi uchun Android planshetida ishlaydigan «O&#39;quvchi o&#39;z-o&#39;ziga xizmat ko&#39;rsatish kioski» loyihasi g&#39;oyasini ishlab chiqing:</p><ol><li>Qurilma qaysi Android imkoniyatlaridan (NFC, kamera, chek printeri) foydalanadi?</li><li>Ilova interfeysi nima uchun oddiy telefon ilovasidan kattaroq va soddaroq bo&#39;lishi kerak?</li></ol><p><strong>Yechim:</strong></p><ol><li><strong>Apparat imkoniyatlari:</strong><ul><li>NFC moduli: O&#39;quvchi ID-kartasini tekkazib to&#39;lov qiladi;</li><li>Kamera / Barcode skaner: Mahsulot shtrix-kodini o&#39;qiydi;</li><li>USB / Bluetooth drayveri: Kvitansiya (chek) chiqaruvchi termoprinterga ulanadi.</li></ul></li><li><strong>Interfeys talablari:</strong><ul><li>Kiosk bolalar va o&#39;quvchilar tomonidan mustaqil ishlatiladi, shuning uchun tugmalar katta bo&#39;lishi kerak;</li><li>Matnlar qisqa va tushunarli piktogrammalar (ikonkalar) bilan birga berilishi shart;</li><li>&quot;Kiosk Mode&quot; yoqilib, o&#39;quvchilar ilovadan chiqib sozlamalarga kira olmasligi ta&#39;minlanadi.</li></ul></li></ol><hr>',14))]),i("div",f,[i("h2",A,[t(o,{name:"file-text"}),a[12]||(a[12]=l(" 5. Tezkor savol-javob (Blits-savollar) ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-tezkor-savol-javob-blits-savollar","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor savol-javob (Blits-savollar)"'},"​",-1))]),a[14]||(a[14]=r("<ol><li><strong>Split-Screen nima?</strong><br><em>Javob:</em> Ekranni ikkita ilova o&#39;rtasida teng bo&#39;lib, ikkalasini bir vaqtda ishlatish imkoniyati.</li><li><strong>Wear OS qaysi turdagi qurilmalar uchun mo&#39;ljallangan?</strong><br><em>Javob:</em> Aqlli soatlar (Smartwatches) uchun.</li><li><strong>Android TV boshqaruvining smartfondan eng asosiy farqi nima?</strong><br><em>Javob:</em> Sensorli boshqaruv yo&#39;q, pult (D-pad) va ovoz orqali boshqariladi.</li><li><strong>On-device AI deganda nima tushuniladi?</strong><br><em>Javob:</em> Sun&#39;iy intellekt modellarining internetga so&#39;rov jo&#39;natmasdan, telefonning o&#39;z protsessorida (NPU) ishlashi.</li><li><strong>IoT nima degani?</strong><br><em>Javob:</em> Internet of Things — Buyumlar interneti (turli maishiy va sanoat qurilmalarining tarmoq orqali o&#39;zaro bog&#39;lanishi).</li></ol><hr>",2))]),i("div",p,[i("h2",c,[t(o,{name:"file-text"}),a[15]||(a[15]=l(" 6. Mentor uchun amaliy tavsiyalar ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-mentor-uchun-amaliy-tavsiyalar","aria-label":'Permalink to "<Icon name="file-text" /> 6. Mentor uchun amaliy tavsiyalar"'},"​",-1))]),a[17]||(a[17]=i("ul",null,[i("li",null,"O'quvchilarga Android dasturchisi faqat smartfon ilovalari bilan cheklanib qolmasdan, aqlli soat, televizor yoki avtomobillar uchun ham ilova yoza olishini tushuntiring."),i("li",null,"Keyingi haftadan boshlab biz Android ekotizimi va Android Studio dasturiy muhiti bilan amaliy tanishishni boshlashimizni e'lon qilib, qiziqishni oshiring.")],-1))])])}const V=n(h,[["render",_]]);export{O as __pageData,V as default};
